def compute(vars):
    flight_attendants = vars["v1"]
    total_employees = vars["v2"]

    if total_employees == 0:
        return None

    value = flight_attendants / total_employees * 100
    return {
        "value": value,
        "trace": {
            "flight_attendants": flight_attendants,
            "total_employees": total_employees,
            "ratio": flight_attendants / total_employees,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
